def algorithm(func, dim, lb, ub, budget, rng):
    D = dim
    n_bests = 5
    sigma = 0.1
    mu = np.zeros(D)
    cov = np.eye(D) * (ub - lb)**2 / 4
    best_f = float('inf')
    best_x = None

    for _ in range(budget):
        if rng.random() < 0.01:
            sigma *= 0.1 + rng.uniform(0, 1)

        z = np.zeros(D)
        v = np.random.multivariate_normal(mu, cov)
        for i in range(n_bests):
            z += v / (n_bests * (sigma**2))
            x = mu + z
            f = func(x)

            if not -5 <= x[0] <= 5:
                continue

            for j in range(1, D):
                if not -5 <= x[j] <= 5:
                    x[j] = np.clip(x[j], lb, ub)
                    break

            f = func(x)
            if f < best_f:
                best_f = f
                best_x = x

        mu += (ub - lb) * sigma**2 / np.sqrt(D) * z
        cov *= 1 + 2 / D - 1 / (D + 3)

    return np.array(best_x)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = clip(np.random.rand(dim))
    x_best = x.copy()
    y_best = func(x)
    best = y_best

    for _ in range(budget - 1):
        v = np.zeros(dim)
        for i in range(dim):
            r = rng.rand(dim)
            r[i] = 0
            v += r * (x_best - x)
        v *= rng.uniform(0.5, 2.0) ** (budget - _ - 1)
        v = clip(v + x)

        y = func(v)
        if y < best:
            best = y
            x_best = v

    return x_best
